def comps(g,color=7):
 pts={(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==color}; res=[]
 while pts:
  st=[pts.pop()]; comp=set(st)
  while st:
   r,c=st.pop()
   for q in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
    if q in pts: pts.remove(q); comp.add(q); st.append(q)
  res.append(comp)
 return sorted(res,key=lambda c:(min(r for r,x in c),min(x for r,x in c)))
for label,g in [('in',di),('out',do)]:
 cs=comps(g)
 print(label,[(len(c),(min(r for r,x in c),max(r for r,x in c),min(x for r,x in c),max(x for r,x in c)),sorted(c)) for c in cs])
